import { useEffect, useState } from "react";

export function SaveToast(id: string) {
  const [saved, setSaved] = useState(false);
  useEffect(() => {
    let alive = true;
    api.save(id).then(() => alive && setSaved(true));
    return () => {
      alive = false;
    };
  }, [id]);
  return saved ? "Saved" : "";
}

